import json, pathlib, re, time, os
from playwright.sync_api import sync_playwright, expect
ROOT=pathlib.Path(__file__).resolve().parents[1]
def run_browser(base, check):
    with sync_playwright() as pw:
        browser=pw.chromium.launch(headless=True, **({'executable_path': os.environ['PLAYWRIGHT_EXECUTABLE_PATH']} if os.environ.get('PLAYWRIGHT_EXECUTABLE_PATH') else {'channel': os.environ['PLAYWRIGHT_CHANNEL']} if os.environ.get('PLAYWRIGHT_CHANNEL') else {}))
        context=browser.new_context(viewport=dict(width=1440,height=1000),reduced_motion='reduce')
        page=context.new_page(); errors=[]; page.on('pageerror',lambda error:errors.append(str(error)))
        artifacts=ROOT/'.test-artifacts'; artifacts.mkdir(exist_ok=True)
        def go(path):
            page.goto(base+'/'+path,wait_until='domcontentloaded')
            if page.locator('script[src*="bootstrap"]').count(): page.wait_for_function("typeof bootstrap !== 'undefined'",timeout=20000)
        def chat(text):
            if page.locator('.assistant-launcher').count() and not page.locator('#assistantPanel').is_visible(): page.locator('.assistant-launcher').click()
            page.locator('#assistantInput').fill(text); page.locator('#assistantSend').click()
            expect(page.locator('#assistantSend')).to_be_enabled(timeout=15000)
            assert not page.locator('#assistantRetry').is_visible(),page.locator('#assistantStatus').inner_text()
        go('catalog.html'); page.wait_for_selector('.book-grid .card'); page.wait_for_function('favoritesAvailable')
        page.locator('.favorite-button').first.click(); page.wait_for_function('favoriteBookIds.length === 1')
        favorite_id=page.evaluate('favoriteBookIds[0]'); check(bool(page.evaluate("localStorage.getItem('savedFavorites')")),'browser guest favorites persist locally')
        page.screenshot(path=str(artifacts/'desktop-catalog.png'),full_page=False)
        go('signup.html')
        for id,value in [('firstNameInput','Browser'),('lastNameInput','Reader'),('emailInput','browser@example.com'),('passwordInput','test-password-123'),('confirmPasswordInput','test-password-123')]: page.locator('#'+id).fill(value)
        page.locator('#signupButton').click(); page.wait_for_url('**/index.html'); page.wait_for_function('favoritesAvailable && favoriteBookIds.length === 1')
        check(page.evaluate('favoriteBookIds[0]')==favorite_id and not page.evaluate("localStorage.getItem('savedFavorites')"),'browser registration merges guest favorites and displays membership')
        expect(page.locator('#memberBenefitsTitle')).to_be_visible(); page.screenshot(path=str(artifacts/'desktop-home.png'),full_page=False)
        go('help.html'); chat('Recommend fantasy'); expect(page.locator('.assistant-book')).to_have_count(3)
        chat('add the second one'); check(page.evaluate('getCartItemCount(loadCartFromStorage())')==2,'browser conversational addition uses actual cart logic')
        go('cart.html'); page.wait_for_selector('#cartTableBody tr')
        before=page.evaluate('getCartItemCount(loadCartFromStorage())'); chat('add book 12 copies')
        page.wait_for_function('(before) => getCartItemCount(loadCartFromStorage()) === before + 12',arg=before)
        page.wait_for_function("document.querySelector('#cartTableBody').innerText.includes('Harry Potter')")
        expect(page.locator('#cartCount')).to_have_text(str(before+12)); check(True,'assistant refreshes visible cart and navbar count')
        # Restored transcript does not replay actions, and explicit receipt replay is idempotent.
        count=page.evaluate('getCartItemCount(loadCartFromStorage())'); page.reload(wait_until='domcontentloaded'); page.wait_for_selector('#cartTableBody tr')
        check(page.evaluate('getCartItemCount(loadCartFromStorage())')==count,'browser transcript restoration cannot duplicate additions')
        check(page.evaluate("async () => { const s=JSON.parse(localStorage.getItem('savedCart')); const id=Object.keys(s.assistantReceipts)[0]; const before=getCartItemCount(s.items); await applyAssistantCartActions([{bookId:1,quantity:2}],id); return getCartItemCount(loadCartFromStorage())===before; }") ,'browser repeated action receipt cannot duplicate additions')
        if page.locator('#assistantPanel').is_visible(): page.locator('#assistantClose').click()
        page.get_by_role('button',name='Checkout',exact=True).click(); page.wait_for_url('**/checkout.html'); expect(page.locator('#placeOrderButton')).to_be_enabled()
        check('Offers save' in page.locator('#checkoutSavings').inner_text(),'checkout displays server-confirmed member savings')
        page.locator('#cardNumberInput').fill('1234567890123456'); page.locator('#cardCvvInput').fill('123'); page.locator('#cardMonthSelect').select_option('12'); page.locator('#cardYearSelect').select_option(str(time.localtime().tm_year+1))
        # Simulate a lost response after the server commits, then safely recover the same receipt.
        dropped=[False]
        def lose_once(route):
            if not dropped[0]: route.fetch(); dropped[0]=True; route.abort()
            else: route.continue_()
        page.route('**/api/orders',lose_once)
        page.locator('#placeOrderButton').click(); expect(page.locator('#retryPurchaseButton')).to_be_visible()
        page.locator('#retryPurchaseButton').click(); expect(page.locator('#orderConfirmation')).to_be_visible()
        first_id=page.locator('#confirmationOrderId').inner_text(); points=int(re.search(r'Points earned: (\d+)',page.locator('#confirmationRewards').inner_text()).group(1))
        check(points>=100,'browser member purchase earns points after confirmed completion')
        page.unroute('**/api/orders',lose_once)
        check(len(context.request.get(base+'/api/customers/me/orders').json())==1,'browser lost-response retry creates exactly one order')
        go('account.html'); expect(page.locator('#accountContent')).to_be_visible(); expect(page.locator('#rewardBalance')).to_have_text(str(points)+' points')
        check('Order #'+first_id in page.locator('#accountOrderList').inner_text(),'account order history and rewards show confirmed purchase')
        go('book.html?id=2'); expect(page.locator('#bookTitle')).to_be_visible()
        page.get_by_role('button',name='Add to Cart',exact=True).click()
        page.wait_for_function('getCartItemCount(loadCartFromStorage()) === 1')
        go('cart.html'); expect(page.locator('#cartTableBody tr')).to_have_count(1)
        page.get_by_role('button',name='Checkout',exact=True).click(); page.wait_for_url('**/checkout.html'); expect(page.locator('#placeOrderButton')).to_be_enabled()
        page.locator('#rewardsSelect').select_option('100'); page.wait_for_function('checkoutQuote && checkoutQuote.rewardDiscount === 5')
        expect(page.locator('#placeOrderButton')).to_be_enabled(); page.locator('#placeOrderButton').click(); expect(page.locator('#orderConfirmation')).to_be_visible()
        check('Rewards redeemed: $5.00' in page.locator('#confirmationRewards').inner_text(),'browser later purchase redeems 100 points for $5 before tax')
        go('help.html'); chat('Show Hunger Games collection'); check(page.locator('.assistant-book').count()>=4,'browser series cards have product links and unavailable status')
        # Keyboard Escape returns focus; mobile has no horizontal page overflow.
        for width,path in [(390,'index.html'),(390,'catalog.html'),(390,'book.html?id=9'),(390,'cart.html'),(390,'account.html'),(390,'help.html')]:
            page.set_viewport_size(dict(width=width,height=844)); go(path)
            expect(page.locator('.site-navbar a[href="account.html"]')).to_contain_text('Browser Reader')
            page.wait_for_timeout(300)
            check(page.evaluate('document.documentElement.scrollWidth <= innerWidth + 1'),'mobile width fits '+path)
        page.screenshot(path=str(artifacts/'mobile-help.png'),full_page=True)
        go('catalog.html'); page.locator('.assistant-launcher').click() if not page.locator('#assistantPanel').is_visible() else None
        page.locator('#assistantInput').focus(); page.keyboard.press('Escape'); expect(page.locator('.assistant-launcher')).to_be_focused()
        page.locator('.assistant-launcher').click(); page.locator('#assistantInput').fill('timeout'); page.locator('#assistantSend').click(); expect(page.locator('#assistantCancel')).to_be_visible(); page.locator('#assistantCancel').click(); expect(page.locator('#assistantSend')).to_be_enabled(); check('cancelled' in page.locator('#assistantStatus').inner_text(),'browser cancellation and keyboard focus work')
        # Admin page and promotion management against same API, in a separate session.
        staff=browser.new_context(viewport=dict(width=1440,height=1000)); staff.request.post(base+'/api/staff/login',data=dict(username='admin',password='admin123'))
        admin=staff.new_page(); admin.on('pageerror',lambda error:errors.append(str(error))); admin.goto(base+'/admin.html#promotions',wait_until='domcontentloaded')
        expect(admin.locator('#promotionList .card').first).to_be_visible()
        admin.locator('#promotionName').fill('Browser public offer'); admin.locator('#promotionPercent').fill('12'); admin.locator('#promotionBooks').select_option(['3','4']); admin.locator('#promotionSave').click()
        expect(admin.locator('#promotionMessage')).to_contain_text('Promotion saved')
        check('Browser public offer' in admin.locator('#promotionList').inner_text(),'administrator can create offers through the internal form')
        admin.locator('#refreshRewards').click(); expect(admin.locator('#internalRewards')).to_contain_text('Browser Reader')
        admin.screenshot(path=str(artifacts/'admin-promotions.png'),full_page=False)
        csv=admin.evaluate('async () => buildOrderCsv(await loadOrdersFromApi())')
        check('Points Earned' in csv and 'Rewards Discount' in csv and 'Browser Reader' in csv,'CSV export includes real account purchase and rewards snapshots')
        check(not errors,'browser pages have no uncaught JavaScript errors: '+str(errors))
        staff.close();context.close();browser.close()
